fn get_column(input: &Vec<Vec<i8>>, j: usize, m: usize, n: usize) -> Vec<i8> {
    // Preconditions assumed to hold: input.len() == n, each row len == m, j < m
    let mut col = Vec::with_capacity(n);
    let mut i = 0;
    while i < n {
        // push input[i][j]
        col.push(input[i][j]);
        i += 1;
    }
    col
}

fn column_stack(input: Vec<Vec<i8>>, m: usize, n: usize) -> Vec<Vec<i8>> {
    // Preconditions assumed to hold: input.len() == n, each row len == m
    let mut result = Vec::with_capacity(m);
    let mut j = 0;
    while j < m {
        // For each column j, extract that column (length n) from input
        let col = get_column(&input, j, m, n);
        result.push(col);
        j += 1;
    }
    result
}